-- PROTECTED FILE - para sa Roblox
local hex_data = [[]]

local function hex_to_bytes(s)
    local out = {}
    for i=1, #s, 2 do
        local b = tonumber(s:sub(i, i+1), 16)
        out[#out+1] = string.char(b)
    end
    return table.concat(out)
end

local encrypted = hex_to_bytes(hex_data)
local key = 0x55
local decoded = ""
for i=1, #encrypted do
    decoded = decoded .. string.char(string.byte(encrypted, i) ~ key)
end

-- Gamitin ang loadstring (Roblox compatible)
local f, err = loadstring(decoded)
if f then
    f()
else
    warn("Protected script error: " .. tostring(err))
end
